        // 负数金额
        assertThrows(IllegalArgumentException.class, () -> FeeCalculator.serviceFee(new BigDecimal("-0.01")));

        // null金额
        assertThrows(IllegalArgumentException.class, () -> FeeCalculator.serviceFee(null));
    }

    private static void assertEquals(BigDecimal expected, BigDecimal actual) {
        if (expected.compareTo(actual) != 0) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }

    private static void assertThrows(Class<? extends Throwable> expectedType, Runnable runnable) {
        try {
            runnable.run();
            throw new AssertionError("Expected " + expectedType.getName() + " to be thrown");
        } catch (Throwable e) {
            if (!expectedType.isInstance(e)) {
                throw new AssertionError("Expected " + expectedType.getName() + " but got " + e.getClass().getName());
            }
        }
    }
